/**
 * The body every non-2xx response carries. The same shape for a refusal the caller can fix and for a fault the caller cannot, so the two are told apart by the status and the code rather than by the body.
 */
export type ErrorResponse = {
    /**
     * The stable machine-readable code. Branch on this, not on the message: the message is written for display and may change.
     */
    code?: string;
    /**
     * A sentence written for a human. Never contains a tenant, a role, a permission, or another row's field value.
     */
    message?: string;
    /**
     * What the caller needs in order to fix the request: the accepted values, the offending field, the current version. Empty when there is nothing to recover from.
     */
    details?: {
        [key: string]: string;
    };
    /**
     * The correlation id. It appears in the server log line for the same failure, which is how a caller quote gets an operator to the right place.
     */
    requestId?: string;
    /**
     * When the body was written, in UTC.
     */
    timestamp?: string;
    /**
     * Whether an unchanged retry could succeed. Null where the server does not claim either way; a client must treat null as unknown, not as false.
     */
    retryable?: boolean;
};

